// tfliteOpsFixtures are outputs of the real TFLite interpreter (LiteRT
// BUILTIN_REF reference kernels) for random one-operator models, generated by
// testdata/tflite_gen/gen_ops.py (provenance in testdata/tflite_gen/OPS.md).
type tfliteOpsFixtures struct {
	Source   string `json:"source"`
	Logistic []struct {
		Scale float64 `json:"scale"`
		ZP    int8    `json:"zp"`
		Out   []int8  `json:"out"` // inputs −128 … 127
	} `json:"logistic"`
	Mul []struct {
		SA  float64 `json:"scaleA"`
		SB  float64 `json:"scaleB"`
		SO  float64 `json:"scaleOut"`
		ZA  int8    `json:"zpA"`
		ZB  int8    `json:"zpB"`
		ZO  int8    `json:"zpOut"`
		Act string  `json:"act"`
		A   []int8  `json:"a"`
		B   []int8  `json:"b"`
		Out []int8  `json:"out"`
	} `json:"mul"`
	Mean []struct {
		In       [3]int  `json:"in"`
		InScale  float64 `json:"inScale"`
		InZP     int8    `json:"inZP"`
		OutScale float64 `json:"outScale"`
		OutZP    int8    `json:"outZP"`
		KeepDims bool    `json:"keepDims"`
		Axes     []int   `json:"axes"`
		Src      []int8  `json:"src"`
		Out      []int8  `json:"out"`
	} `json:"mean"`
	Quantize []struct {
		InScale  float64 `json:"inScale"`
		InZP     int8    `json:"inZP"`
		OutScale float64 `json:"outScale"`
		OutZP    int8    `json:"outZP"`
		Src      []int8  `json:"src"`
		Out      []int8  `json:"out"`
	} `json:"quantize"`
	Concat []struct {
		Shapes [][3]int `json:"shapes"` // [H, W, C] per input
		Axis   int      `json:"axis"`   // 1 … 3 (NHWC)
		Srcs   [][]int8 `json:"srcs"`
		Out    []int8   `json:"out"`
	} `json:"concat"`
	Pad []struct {
		In    [3]int    `json:"in"`
		Pads  [3][2]int `json:"pads"` // H, W, C (before, after)
		V2    bool      `json:"v2"`
		OutZP int8      `json:"outZP"`
		Value int8      `json:"value"`
		Src   []int8    `json:"src"`
		Out   []int8    `json:"out"`
	} `json:"pad"`
	Resize []struct {
		In           [3]int `json:"in"`
		OutH         int    `json:"outH"`
		OutW         int    `json:"outW"`
		AlignCorners bool   `json:"alignCorners"`
		HalfPixel    bool   `json:"halfPixel"`
		Src          []int8 `json:"src"`
		Out          []int8 `json:"out"`
	} `json:"resize"`
}

var tfliteOps *tfliteOpsFixtures

func loadTFLiteOps(t *testing.T) *tfliteOpsFixtures {
	t.Helper()
	if tfliteOps != nil {
		return tfliteOps
	}
	f, err := os.Open("testdata/tflite_ops.json.gz")
	require.NoError(t, err)
	defer f.Close()
	z, err := gzip.NewReader(f)
	require.NoError(t, err)
	var fx tfliteOpsFixtures
	require.NoError(t, json.NewDecoder(z).Decode(&fx))
	tfliteOps = &fx
	return tfliteOps
}

func shapeOf(s [3]int) Shape { return Shape{H: s[0], W: s[1], C: s[2]} }

// tfliteActRange is TFLite's CalculateActivationRangeQuantized for int8:
// zp + roundf(f/scale) with the division in float32.
func tfliteActRange(act string, scale float32, zp int8) (int8, int8) {
	q := func(f float32) int32 { return int32(zp) + int32(math.Round(float64(f/scale))) }
	lo, hi := int32(-128), int32(127)
	switch act {
	case "relu":
		lo = max(lo, q(0))
	case "relu6":
		lo, hi = max(lo, q(0)), min(hi, q(6))
	case "relun1to1":
		lo, hi = max(lo, q(-1)), min(hi, q(1))
	}
	return int8(lo), int8(hi)
}

// diffCount returns the number of differing elements.
func diffCount(a, b []int8) int {
	n := 0
	for i := range a {
		if a[i] != b[i] {
			n++
		}
	}
	return n
}

func ramp() []int8 {
	x := make([]int8, 256)
	for i := range x {
		x[i] = int8(i - 128)
	}
	return x
}

// ---- interpreter fixtures

func TestLogisticTFLite(t *testing.T) {
	fx := loadTFLiteOps(t)
	m := &mismatchLog{t: t}
	src, dst := ramp(), make([]int8, 256)
	f64Diff := 0
	for i, c := range fx.Logistic {
		p, err := QuantizeLogistic(float32(c.Scale), c.ZP)
		require.NoError(t, err, "case %d", i)
		require.NoError(t, Logistic(dst, src, p))
		m.compare(func() string { return fmt.Sprintf("logistic %d scale=%g zp=%d", i, c.Scale, c.ZP) }, dst, c.Out)
		for x := range 256 { // float64 evaluation of the same formula
			d := float64(float32(c.Scale)) * float64(x-128-int(c.ZP))
			q := math.Round(256/(1+math.Exp(-d))) - 128
			if int8(min(max(q, -128), 127)) != c.Out[x] {
				f64Diff++
			}
		}
	}
	m.done()
	t.Logf("a float64 table would differ on %d of %d outputs", f64Diff, m.out)
	assert.Positive(t, f64Diff, "fixtures must distinguish float32 and float64 table arithmetic")
}

func TestMulTFLite(t *testing.T) {
	fx := loadTFLiteOps(t)
	m := &mismatchLog{t: t}
	exactDiff, f64Diff := 0, 0
	forms := [3]int{}
	acts := map[string]int{}
	for i, c := range fx.Mul {
		rq, err := QuantizeMul(float32(c.SA), float32(c.SB), float32(c.SO))
		require.NoError(t, err, "case %d", i)
		p := MulParams{ZPA: c.ZA, ZPB: c.ZB, ZPOut: c.ZO, RQ: rq, Round: RoundTFLite}
		p.Min, p.Max = tfliteActRange(c.Act, float32(c.SO), c.ZO)
		dst := make([]int8, len(c.A))
		require.NoError(t, Mul(dst, c.A, c.B, p), "case %d", i)
		m.compare(func() string { return fmt.Sprintf("mul %d %+v", i, p) }, dst, c.Out)

		p.Round = RoundExact
		require.NoError(t, Mul(dst, c.A, c.B, p))
		exactDiff += diffCount(dst, c.Out)
		p.Round = RoundTFLite
		p.RQ, err = QuantizeMultiplier(float64(float32(c.SA)) * float64(float32(c.SB)) / float64(float32(c.SO)))
		require.NoError(t, err)
		require.NoError(t, Mul(dst, c.A, c.B, p))
		f64Diff += diffCount(dst, c.Out)

		switch len(c.B) {
		case len(c.A):
			forms[0]++
		case 1:
			forms[2]++
		default:
			forms[1]++
		}
		acts[c.Act]++
	}
	m.done()
	t.Logf("broadcast forms (same, channel, scalar)=%v activations=%v", forms, acts)
	t.Logf("RoundExact would differ on %d outputs, a float64 multiplier on %d", exactDiff, f64Diff)
	assert.Positive(t, exactDiff, "fixtures must distinguish the rounding modes")
	assert.Positive(t, f64Diff, "fixtures must distinguish float32 and float64 multiplier derivation")
	for _, n := range forms {
		assert.Positive(t, n)
	}
	assert.Len(t, acts, 4)
}

func TestMeanTFLite(t *testing.T) {
	fx := loadTFLiteOps(t)
	m := &mismatchLog{t: t}
	exactDiff, twoStepDiff, roundFoldDiff := 0, 0, 0
	for i, c := range fx.Mean {
		rq, err := QuantizeMean(float32(c.InScale), float32(c.OutScale))
		require.NoError(t, err, "case %d", i)
		in := shapeOf(c.In)
		p := MeanParams{InZP: c.InZP, OutZP: c.OutZP, RQ: rq, Round: RoundTFLite}
		dst := make([]int8, in.C)
		require.NoError(t, MeanHW(dst, c.Src, in, p), "case %d", i)
		m.compare(func() string {
			return fmt.Sprintf("mean %d in=%v keep=%v axes=%v %+v", i, in, c.KeepDims, c.Axes, p)
		}, dst, c.Out)
		p.Round = RoundExact
		require.NoError(t, MeanHW(dst, c.Src, in, p))
		exactDiff += diffCount(dst, c.Out)
		// Older TFLite (integer_ops::Mean): requantise the sum, then divide
		// by n rounding half away from zero.
		n := int32(in.H * in.W)
		fold := meanTFLiteRequant(rq, int(n))
		roundFold := fold // the fold with a rounded instead of truncating division
		roundFold.Mult = int32((int64(rq.Mult)<<uint(rq.Shift-fold.Shift) + int64(n/2)) / int64(n))
		alt := make([]int8, in.C)
		for ch := range dst {
			var acc int32
			for j := ch; j < len(c.Src); j += in.C {
				acc += int32(c.Src[j]) - int32(c.InZP)
			}
			v := rq.ApplyTFLite(acc)
			if v > 0 {
				v = (v + n/2) / n
			} else {
				v = (v - n/2) / n
			}
			dst[ch] = int8(min(max(v+int32(c.OutZP), -128), 127))
			alt[ch] = int8(min(max(roundFold.ApplyTFLite(acc)+int32(c.OutZP), -128), 127))
		}
		twoStepDiff += diffCount(dst, c.Out)
		roundFoldDiff += diffCount(alt, c.Out)
	}
	m.done()
	t.Logf("RoundExact would differ on %d outputs, requantise-then-divide on %d, a rounded 1/n fold on %d",
		exactDiff, twoStepDiff, roundFoldDiff)
	assert.Positive(t, exactDiff, "fixtures must distinguish the rounding modes")
	assert.Positive(t, twoStepDiff, "fixtures must distinguish the 1/n folding")
	assert.Positive(t, roundFoldDiff, "fixtures must pin the truncating 1/n fold")
}

func TestRequantizeTFLite(t *testing.T) {
	fx := loadTFLiteOps(t)
	m := &mismatchLog{t: t}
	exactDiff := 0
	ratios := [3]int{} // <1, =1, >1
	for i, c := range fx.Quantize {
		rq, err := QuantizeRequantize(float32(c.InScale), float32(c.OutScale))
		require.NoError(t, err, "case %d", i)
		p := RequantizeParams{InZP: c.InZP, OutZP: c.OutZP, RQ: rq, Round: RoundTFLite}
		dst := make([]int8, len(c.Src))
		require.NoError(t, Requantize(dst, c.Src, p), "case %d", i)
		m.compare(func() string { return fmt.Sprintf("quantize %d %+v", i, p) }, dst, c.Out)
		p.Round = RoundExact
		require.NoError(t, Requantize(dst, c.Src, p))
		exactDiff += diffCount(dst, c.Out)
		switch r := float32(c.InScale) / float32(c.OutScale); {
		case r < 1:
			ratios[0]++
		case r == 1:
			ratios[1]++
		default:
			ratios[2]++
		}
	}
	m.done()
	t.Logf("scale ratios (<1, =1, >1)=%v; RoundExact would differ on %d outputs", ratios, exactDiff)
	assert.Positive(t, exactDiff, "fixtures must distinguish the rounding modes")
	for _, n := range ratios {
		assert.Positive(t, n)
	}
}

func TestConcatTFLite(t *testing.T) {
	fx := loadTFLiteOps(t)
	m := &mismatchLog{t: t}
	axes := map[int]int{}
	for i, c := range fx.Concat {
		outer := 1
		for _, d := range c.Shapes[0][:c.Axis-1] {
			outer *= d
		}
		dst := make([]int8, len(c.Out))
		require.NoError(t, Concat(dst, c.Srcs, outer), "case %d", i)
		m.compare(func() string { return fmt.Sprintf("concat %d shapes=%v axis=%d", i, c.Shapes, c.Axis) }, dst, c.Out)
		axes[c.Axis*10+len(c.Srcs)]++
	}
	m.done()
	assert.Len(t, axes, 9, "every axis 1..3 × 2..4 inputs")
}

func TestPadTFLite(t *testing.T) {
	fx := loadTFLiteOps(t)
	m := &mismatchLog{t: t}
	for i, c := range fx.Pad {
		if !c.V2 {
			require.Equal(t, c.OutZP, c.Value, "PAD pads with the output zero point")
		}
		p := PadParams{
			In: shapeOf(c.In), Top: c.Pads[0][0], Bottom: c.Pads[0][1],
			Left: c.Pads[1][0], Right: c.Pads[1][1], Front: c.Pads[2][0], Back: c.Pads[2][1],
			Value: c.Value,
		}
		out, err := p.OutShape()
		require.NoError(t, err)
		dst := make([]int8, out.Len())
		require.NoError(t, Pad(dst, c.Src, p), "case %d", i)
		m.compare(func() string { return fmt.Sprintf("pad %d %+v", i, p) }, dst, c.Out)
	}
	m.done()
}

func TestResizeNearestTFLite(t *testing.T) {
	fx := loadTFLiteOps(t)
	m := &mismatchLog{t: t}
	flags := map[[2]bool]int{}
	for i, c := range fx.Resize {
		p := ResizeParams{In: shapeOf(c.In), OutH: c.OutH, OutW: c.OutW, AlignCorners: c.AlignCorners, HalfPixel: c.HalfPixel}
		dst := make([]int8, len(c.Out))
		require.NoError(t, ResizeNearest(dst, c.Src, p), "case %d", i)
		m.compare(func() string { return fmt.Sprintf("resize %d %+v", i, p) }, dst, c.Out)
		flags[[2]bool{c.AlignCorners, c.HalfPixel}]++
	}
	m.done()
	assert.Len(t, flags, 4)
}

// ---- exact-mode references (big-rational, see reference_test.go)

// quantizeRat is quantizeReal for a rational value.
func quantizeRat(y, sOut *big.Rat, zp, lo, hi int8) int8 {
	r := new(big.Rat).Quo(y, sOut)
	q := roundHalfAway(r)
	q.Add(q, big.NewInt(int64(zp)))
	return clampBig(q, lo, hi)
}

func TestMulReference(t *testing.T) {
	g := newGen(21)
	m := &mismatchLog{t: t}
	for c := range 2000 {
		e := &exactF{}
		rq := g.requant()
		sc := newRefScales(g.r, e, []Requant{rq}) // sIn·sW/sOut = M'
		p := MulParams{ZPA: g.zp(), ZPB: g.zp(), ZPOut: g.zp(), RQ: rq}
		p.Min, p.Max = g.act(sc.outScale(), p.ZPOut)
		n := 1 + g.r.IntN(48)
		nb := []int{n, 1, 0}[g.r.IntN(3)]
		if nb == 0 { // channel broadcast: a divisor of n
			nb = n
			for d := 2; d < n; d++ {
				if n%d == 0 && g.r.IntN(2) == 0 {
					nb = d
					break
				}
			}
		}
		a, b := g.int8s(n), g.int8s(nb)
		if rq.Shift > -8 || g.r.IntN(8) == 0 {
			for i := range a {
				a[i] = nearZP(g, p.ZPA)
			}
			for i := range b {
				b[i] = nearZP(g, p.ZPB)
			}
		}
		want := make([]int8, n)
		xa, xb := dequant(e, a, p.ZPA, sc.sIn), dequant(e, b, p.ZPB, sc.sW[0])
		for i := range want {
			want[i] = quantizeReal(e.mul(xa[i], xb[i%nb]), sc.sOut, p.ZPOut, p.Min, p.Max)
		}
		require.False(t, e.inexact, "reference arithmetic was inexact")
		got := make([]int8, n)
		require.NoError(t, Mul(got, a, b, p))
		m.compare(func() string { return fmt.Sprintf("case %d %+v nb=%d", c, p, nb) }, got, want)
	}
	m.done()
}

func TestRequantizeReference(t *testing.T) {
	g := newGen(22)
	m := &mismatchLog{t: t}
	for c := range 1500 {
		e := &exactF{}
		rq := g.requant()
		sc := newRefScales(g.r, e, []Requant{rq})
		sIn := e.mul(sc.sIn, sc.sW[0]) // sIn/sOut = M'
		p := RequantizeParams{InZP: g.zp(), OutZP: g.zp(), RQ: rq}
		src := ramp()
		want := make([]int8, len(src))
		for i, x := range dequant(e, src, p.InZP, sIn) {
			want[i] = quantizeReal(x, sc.sOut, p.OutZP, -128, 127)
		}
		require.False(t, e.inexact, "reference arithmetic was inexact")
		got := make([]int8, len(src))
		require.NoError(t, Requantize(got, src, p))
		m.compare(func() string { return fmt.Sprintf("case %d %+v", c, p) }, got, want)
	}
	m.done()
}

func TestMeanReference(t *testing.T) {
	g := newGen(23)
	m := &mismatchLog{t: t}
	for c := range 1500 {
		e := &exactF{}
		rq := g.requant()
		if g.r.IntN(3) > 0 {
			rq = Requant{Mult: 1<<30 + g.r.Int32N(1<<30), Shift: int32(-3 + g.r.IntN(5))}
		}
		sc := newRefScales(g.r, e, []Requant{rq})
		sIn := e.mul(sc.sIn, sc.sW[0])
		in := Shape{H: 1 + g.r.IntN(9), W: 1 + g.r.IntN(9), C: 1 + g.r.IntN(12)}
		p := MeanParams{InZP: g.zp(), OutZP: g.zp(), RQ: rq}
		src := g.int8s(in.Len())
		count := big.NewRat(int64(in.H*in.W), 1)
		xs := dequant(e, src, p.InZP, sIn)
		want := make([]int8, in.C)
		for ch := range want {
			sum := new(big.Rat)
			for i := ch; i < len(xs); i += in.C {
				r, _ := xs[i].Rat(nil)
				sum.Add(sum, r)
			}
			want[ch] = quantizeRat(sum.Quo(sum, count), sc.sOut, p.OutZP, -128, 127)
		}
		require.False(t, e.inexact, "reference arithmetic was inexact")
		got := make([]int8, in.C)
		require.NoError(t, MeanHW(got, src, in, p))
		m.compare(func() string { return fmt.Sprintf("case %d in=%v %+v", c, in, p) }, got, want)
	}
	m.done()
}

// TestMeanExactRounding checks meanExact against big.Rat over the full
// accumulator, count and shift ranges (large counts the shape test cannot
// afford).
func TestMeanExactRounding(t *testing.T) {
	g := newGen(24)
	m := &mismatchLog{t: t}
	for shift := int32(MinShift); shift <= MaxShift; shift++ {
		got, want := make([]int8, 0, 400), make([]int8, 0, 400)
		for range 400 {
			count := 1 + g.r.IntN(maxMeanCount)
			if g.r.IntN(2) == 0 {
				count = 1 + g.r.IntN(64)
			}
			bound := 255 * count
			acc := int32(g.r.IntN(2*bound+1) - bound)
			mult := []int32{1 << 30, 3 << 29, math.MaxInt32, 1<<30 + g.r.Int32N(1<<30)}[g.r.IntN(4)]
			rq := Requant{Mult: mult, Shift: shift}
			r := new(big.Rat).SetFrac(
				new(big.Int).Mul(big.NewInt(int64(acc)), big.NewInt(int64(mult))),
				new(big.Int).Lsh(big.NewInt(int64(count)), uint(31-shift)))
			if roundHalfAway(r).Cmp(big.NewInt(meanExact(acc, rq, count))) == 0 {
				got = append(got, 0)
			} else {
				got = append(got, 1)
			}
			want = append(want, 0)
		}
		m.compare(func() string { return fmt.Sprintf("shift=%d", shift) }, got, want)
	}
	m.done()
}

// ---- hand cases

func TestTFLiteOpsHand(t *testing.T) {
	// QUANTIZE with equal scales is the identity on (x − zp).
	rq, err := QuantizeRequantize(0.1, 0.1)
	require.NoError(t, err)
	assert.Equal(t, Requant{Mult: 1 << 30, Shift: 1}, rq)

	// MEAN folds 1/count into the multiplier: 0.5/3 → ⌊2^30·2/3⌋, shift −1.
	assert.Equal(t, Requant{Mult: 715827882, Shift: -1}, meanTFLiteRequant(Requant{Mult: 1 << 30, Shift: 0}, 3))
	assert.Equal(t, Requant{Mult: 1 << 30, Shift: 0}, meanTFLiteRequant(Requant{Mult: 1 << 30, Shift: 0}, 1))
	assert.Equal(t, Requant{Mult: 214748364, Shift: -31}, meanTFLiteRequant(Requant{Mult: 1 << 30, Shift: -31}, 5), "k clamped to 31+Shift = 0")

	// MUL: (5−1)·(−3−0)·0.25 = −3.
	dst := make([]int8, 2)
	p := MulParams{ZPA: 1, RQ: Requant{Mult: 1 << 30, Shift: -1}, Min: -128, Max: 127}
	require.NoError(t, Mul(dst, []int8{5, 1}, []int8{-3}, p))
	assert.Equal(t, []int8{-3, 0}, dst)
	// Tie: 1·1·0.5 rounds to 1 in both modes, −1·1·0.5 to −1 (exact) / 0 (TFLite).
	p = MulParams{RQ: Requant{Mult: 1 << 30, Shift: 0}, Min: -128, Max: 127}
	require.NoError(t, Mul(dst, []int8{1, -1}, []int8{1}, p))
	assert.Equal(t, []int8{1, -1}, dst)
	p.Round = RoundTFLite
	require.NoError(t, Mul(dst, []int8{1, -1}, []int8{1}, p))
	assert.Equal(t, []int8{1, 0}, dst)

	// LOGISTIC: input 0 (at the zero point) → 0.5 → 128−128 = 0.
	lp, err := QuantizeLogistic(0.1, 7)
	require.NoError(t, err)
	assert.Equal(t, int8(0), lp.Table[7])
	assert.Equal(t, int8(-128), lp.Table[128], "input −128: σ(−13.5)·256 < 0.5")

	// CONCATENATION on channels of a 1×2 image: [a0 a1 | b0] per pixel.
	out := make([]int8, 6)
	require.NoError(t, Concat(out, [][]int8{{1, 2, 3, 4}, {9, 8}}, 2))
	assert.Equal(t, []int8{1, 2, 9, 3, 4, 8}, out)

	// PAD 1×1×1 by one row/column on each side and one channel in front.
	pp := PadParams{In: Shape{H: 1, W: 1, C: 1}, Top: 1, Right: 1, Front: 1, Value: -5}
	ps, err := pp.OutShape()
	require.NoError(t, err)
	assert.Equal(t, Shape{H: 2, W: 2, C: 2}, ps)
	pd := make([]int8, ps.Len())
	require.NoError(t, Pad(pd, []int8{42}, pp))
	assert.Equal(t, []int8{-5, -5, -5, -5, -5, 42, -5, -5}, pd)

	// RESIZE 2×2 → 4×4 (YOLO upsample): each pixel repeated 2×2.
	rd := make([]int8, 16)
	require.NoError(t, ResizeNearest(rd, []int8{1, 2, 3, 4}, ResizeParams{In: Shape{H: 2, W: 2, C: 1}, OutH: 4, OutW: 4}))
	assert.Equal(t, []int8{1, 1, 2, 2, 1, 1, 2, 2, 3, 3, 4, 4, 3, 3, 4, 4}, rd)
}

func TestTFLiteOpsAlias(t *testing.T) {
	g := newGen(25)
	src := g.int8s(300)

	lp, err := QuantizeLogistic(0.05, -3)
	require.NoError(t, err)
	want := make([]int8, len(src))
	require.NoError(t, Logistic(want, src, lp))
	got := append([]int8(nil), src...)
	require.NoError(t, Logistic(got, got, lp))
	assert.Equal(t, want, got, "Logistic in place")

	b := g.int8s(30)
	for _, round := range []Rounding{RoundExact, RoundTFLite} {
		mp := MulParams{ZPA: 3, ZPB: -9, ZPOut: 1, RQ: Requant{Mult: 3 << 29, Shift: -7}, Min: -128, Max: 127, Round: round}
		require.NoError(t, Mul(want, src, b, mp))
		got = append(got[:0], src...)
		require.NoError(t, Mul(got, got, b, mp))
		assert.Equal(t, want, got, "Mul in place")

		rp := RequantizeParams{InZP: 3, OutZP: -2, RQ: Requant{Mult: 5 << 28, Shift: 1}, Round: round}
		require.NoError(t, Requantize(want, src, rp))
		got = append(got[:0], src...)
		require.NoError(t, Requantize(got, got, rp))
		assert.Equal(t, want, got, "Requantize in place")
	}
}

// ---- errors and allocations

func TestTFLiteOpsQuantizeErrors(t *testing.T) {
	inf, nan := float32(math.Inf(1)), float32(math.NaN())
	for _, s := range []float32{0, -1, inf, nan} {
		_, err := QuantizeLogistic(s, 0)
		assert.Equal(t, ErrRequant, err, "logistic %v", s)
		for _, f := range []func() (Requant, error){
			func() (Requant, error) { return QuantizeMul(s, 1, 1) },
			func() (Requant, error) { return QuantizeMul(1, s, 1) },
			func() (Requant, error) { return QuantizeMul(1, 1, s) },
			func() (Requant, error) { return QuantizeMean(s, 1) },
			func() (Requant, error) { return QuantizeMean(1, s) },
			func() (Requant, error) { return QuantizeRequantize(s, 1) },
			func() (Requant, error) { return QuantizeRequantize(1, s) },
		} {
			_, err := f()
			assert.Equal(t, ErrRequant, err, "scale %v", s)
		}
	}
	// Unrepresentable: float32 product underflows to 0 or overflows to +Inf.
	_, err := QuantizeMul(1e-30, 1e-30, 1)
	assert.Equal(t, ErrRequant, err)
	_, err = QuantizeMul(1e30, 1e30, 1)
	assert.Equal(t, ErrRequant, err)
	_, err = QuantizeMean(1e30, 1e-30)
	assert.Equal(t, ErrRequant, err)
	_, err = QuantizeRequantize(1e-30, 1e30)
	assert.Equal(t, ErrRequant, err)
}

func TestTFLiteOpsErrors(t *testing.T) {
	x := make([]int8, 12)
	ok := Requant{Mult: 1 << 30, Shift: 0}
	bad := Requant{Mult: 5, Shift: 0}

	assert.Equal(t, ErrLength, Logistic(x[:3], x, LogisticParams{}))

	mp := MulParams{RQ: ok, Min: -128, Max: 127}
	assert.NoError(t, Mul(x, x, x[:4], mp))
	assert.NoError(t, Mul(x[:0], x[:0], x[:1], mp))
	assert.Equal(t, ErrLength, Mul(x[:11], x, x, mp), "dst length")
	assert.Equal(t, ErrLength, Mul(x, x, x[:0], mp), "empty b")
	assert.Equal(t, ErrLength, Mul(x, x, x[:5], mp), "b does not divide a")
	assert.Equal(t, ErrRequant, Mul(x, x, x, MulParams{RQ: bad, Max: 127}))
	assert.Equal(t, ErrRequant, Mul(x, x, x, MulParams{RQ: ok, Max: 127, Round: 2}))
	assert.Equal(t, ErrActivation, Mul(x, x, x, MulParams{RQ: ok, Min: 1, Max: 0}))

	in := Shape{H: 2, W: 2, C: 3}
	ep := MeanParams{RQ: ok}
	assert.NoError(t, MeanHW(x[:3], x, in, ep))
	assert.Equal(t, ErrShape, MeanHW(x[:3], x, Shape{H: 0, W: 2, C: 3}, ep))
	assert.Equal(t, ErrShape, MeanHW(x[:1], x, Shape{H: MaxElements, W: 2, C: 1}, ep), "too many elements")
	assert.Equal(t, ErrShape, MeanHW(x[:1], x, Shape{H: 3000, W: 3000, C: 1}, ep), "H·W sum may overflow int32")
	assert.Equal(t, ErrLength, MeanHW(x[:2], x, in, ep))
	assert.Equal(t, ErrLength, MeanHW(x[:3], x[:11], in, ep))
	assert.Equal(t, ErrRequant, MeanHW(x[:3], x, in, MeanParams{RQ: bad}))
	assert.Equal(t, ErrRequant, MeanHW(x[:3], x, in, MeanParams{RQ: ok, Round: 9}))

	assert.Equal(t, ErrLength, Requantize(x[:3], x, RequantizeParams{RQ: ok}))
	assert.Equal(t, ErrRequant, Requantize(x, x, RequantizeParams{RQ: bad}))
	assert.Equal(t, ErrRequant, Requantize(x, x, RequantizeParams{RQ: ok, Round: 2}))

	assert.NoError(t, Concat(nil, nil, 1))
	assert.NoError(t, Concat(x[:6], [][]int8{x[6:9], nil, x[9:]}, 3))
	assert.Equal(t, ErrShape, Concat(x, [][]int8{x}, 0))
	assert.Equal(t, ErrShape, Concat(x, [][]int8{x}, -1))
	assert.Equal(t, ErrLength, Concat(x[:6], [][]int8{x[:4], x[:2]}, 4), "not a multiple of outer")
	assert.Equal(t, ErrLength, Concat(x[:6], [][]int8{x[:4], x[:4]}, 2), "too long")
	assert.Equal(t, ErrLength, Concat(x[:6], [][]int8{x[:2], x[:2]}, 2), "too short")

	pin := PadParams{In: Shape{H: 1, W: 2, C: 3}, Top: 1}
	assert.NoError(t, Pad(x, x[:6], pin))
	for _, c := range []PadParams{
		{In: Shape{H: 0, W: 2, C: 3}},
		{In: Shape{H: 1, W: 2, C: 3}, Top: -1},
		{In: Shape{H: 1, W: 2, C: 3}, Back: -1},
		{In: Shape{H: 1, W: 2, C: 3}, Left: MaxElements},
		{In: Shape{H: 1, W: 2, C: 3}, Front: MaxElements, Back: MaxElements},
		{In: Shape{H: 1, W: 2, C: 3}, Top: 1 << 15, Left: 1 << 15},
	} {
		_, err := c.OutShape()
		assert.Equal(t, ErrShape, err, "%+v", c)
		assert.Equal(t, ErrShape, Pad(x, x[:6], c), "%+v", c)
	}
	assert.Equal(t, ErrLength, Pad(x[:11], x[:6], pin))
	assert.Equal(t, ErrLength, Pad(x, x[:5], pin))

	rp := ResizeParams{In: Shape{H: 1, W: 2, C: 3}, OutH: 2, OutW: 2}
	assert.NoError(t, ResizeNearest(x, x[:6], rp))
	assert.Equal(t, ErrShape, ResizeNearest(x, x[:6], ResizeParams{In: Shape{H: 1, W: 0, C: 3}, OutH: 2, OutW: 2}))
	assert.Equal(t, ErrShape, ResizeNearest(x, x[:6], ResizeParams{In: rp.In, OutH: 0, OutW: 2}))
	assert.Equal(t, ErrShape, ResizeNearest(x, x[:6], ResizeParams{In: rp.In, OutH: MaxElements, OutW: 2}))
	assert.Equal(t, ErrLength, ResizeNearest(x[:11], x[:6], rp))
	assert.Equal(t, ErrLength, ResizeNearest(x, x[:7], rp))
}

func TestTFLiteOpsNoAllocs(t *testing.T) {
	src, dst := make([]int8, 4*4*8), make([]int8, 4*4*8)
	b := make([]int8, 8)
	up := make([]int8, 8*8*8)
	rq := Requant{Mult: 3 << 29, Shift: -6}
	lp, err := QuantizeLogistic(0.03, 5)
	require.NoError(t, err)
	srcs := [][]int8{src[:64], src[64:]}
	pp := PadParams{In: Shape{H: 4, W: 4, C: 8}, Top: 1, Bottom: 2, Left: 1, Front: 1, Back: 1}
	ps, err := pp.OutShape()
	require.NoError(t, err)
	pd := make([]int8, ps.Len())
	for _, round := range []Rounding{RoundExact, RoundTFLite} {
		mp := MulParams{ZPA: 1, ZPB: 2, RQ: rq, Min: -128, Max: 127, Round: round}
		ep := MeanParams{InZP: 1, OutZP: -1, RQ: rq, Round: round}
		qp := RequantizeParams{InZP: 1, OutZP: -1, RQ: rq, Round: round}
		for name, f := range map[string]func(){
			"QuantizeLogistic": func() { _, _ = QuantizeLogistic(0.03, 5) },
			"Logistic":         func() { _ = Logistic(dst, src, lp) },
			"Logistic error":   func() { _ = Logistic(dst[:1], src, lp) },
			"QuantizeMul":      func() { _, _ = QuantizeMul(0.1, 0.2, 0.3) },
			"Mul":              func() { _ = Mul(dst, src, b, mp) },
			"Mul error":        func() { _ = Mul(dst[:1], src, b, mp) },
			"QuantizeMean":     func() { _, _ = QuantizeMean(0.1, 0.3) },
			"MeanHW":           func() { _ = MeanHW(dst[:8], src, Shape{H: 4, W: 4, C: 8}, ep) },
			"MeanHW error":     func() { _ = MeanHW(dst[:7], src, Shape{H: 4, W: 4, C: 8}, ep) },
			"Requantize":       func() { _ = Requantize(dst, src, qp) },
			"Requantize error": func() { _ = Requantize(dst[:1], src, qp) },
			"Concat":           func() { _ = Concat(dst, srcs, 4) },
			"Concat error":     func() { _ = Concat(dst[:1], srcs, 4) },
			"Pad":              func() { _ = Pad(pd, src, pp) },
			"Pad error":        func() { _ = Pad(pd[:1], src, pp) },
			"ResizeNearest":    func() { _ = ResizeNearest(up, src, ResizeParams{In: Shape{H: 4, W: 4, C: 8}, OutH: 8, OutW: 8}) },
			"Resize error":     func() { _ = ResizeNearest(up[:1], src, ResizeParams{In: Shape{H: 4, W: 4, C: 8}, OutH: 8, OutW: 8}) },
		} {
			assert.Zero(t, testing.AllocsPerRun(50, f), "%s round=%d", name, round)
		}
	}
}

