// gen_ops.py --ops2)

type tfliteOps2Fixtures struct {
	Source    string `json:"source"`
	LeakyReLU []struct {
		InScale  float64 `json:"inScale"`
		InZP     int8    `json:"inZP"`
		OutScale float64 `json:"outScale"`
		OutZP    int8    `json:"outZP"`
		Alpha    float64 `json:"alpha"`
		Out      []int8  `json:"out"` // inputs −128 … 127
	} `json:"leakyRelu"`
	Bilinear []struct {
		In           [3]int `json:"in"`
		OutH         int    `json:"outH"`
		OutW         int    `json:"outW"`
		AlignCorners bool   `json:"alignCorners"`
		HalfPixel    bool   `json:"halfPixel"`
		Src          []int8 `json:"src"`
		Out          []int8 `json:"out"`
	} `json:"bilinear"`
}

var tfliteOps2 *tfliteOps2Fixtures

func loadTFLiteOps2(t *testing.T) *tfliteOps2Fixtures {
	t.Helper()
	if tfliteOps2 != nil {
		return tfliteOps2
	}
	f, err := os.Open("testdata/tflite_ops2.json.gz")
	require.NoError(t, err)
	defer f.Close()
	z, err := gzip.NewReader(f)
	require.NoError(t, err)
	var fx tfliteOps2Fixtures
	require.NoError(t, json.NewDecoder(z).Decode(&fx))
	tfliteOps2 = &fx
	return tfliteOps2
}

func TestLeakyReLUTFLite(t *testing.T) {
	fx := loadTFLiteOps2(t)
	m := &mismatchLog{t: t}
	src, dst := ramp(), make([]int8, 256)
	exactDiff, f64Diff, orderDiff := 0, 0, 0
	var equal, zeroAlpha, bigAlpha int
	for i, c := range fx.LeakyReLU {
		si, so, a := float32(c.InScale), float32(c.OutScale), float32(c.Alpha)
		id, al, err := QuantizeLeakyReLU(si, so, a)
		require.NoError(t, err, "case %d", i)
		p := LeakyReLUParams{InZP: c.InZP, OutZP: c.OutZP, Identity: id, Alpha: al, Round: RoundTFLite}
		require.NoError(t, LeakyReLU(dst, src, p), "case %d", i)
		m.compare(func() string { return fmt.Sprintf("leaky %d alpha=%g %+v", i, c.Alpha, p) }, dst, c.Out)

		p.Round = RoundExact
		require.NoError(t, LeakyReLU(dst, src, p))
		exactDiff += diffCount(dst, c.Out)
		p.Round = RoundTFLite
		// float64 derivation
		p.Identity, err = quantizeMultiplierTFLite(float64(si) / float64(so))
		require.NoError(t, err)
		p.Alpha, err = quantizeMultiplierTFLite(float64(si) * float64(a) / float64(so))
		require.NoError(t, err)
		require.NoError(t, LeakyReLU(dst, src, p))
		f64Diff += diffCount(dst, c.Out)
		// float32 with the other association: inScale·(alpha/outScale)
		p.Identity = id
		p.Alpha, err = quantizeMultiplierTFLite(float64(float32(si * float32(a/so))))
		require.NoError(t, err)
		require.NoError(t, LeakyReLU(dst, src, p))
		orderDiff += diffCount(dst, c.Out)

		if si == so {
			equal++
		}
		if a == 0 {
			zeroAlpha++
		}
		if a > 1 {
			bigAlpha++
		}
	}
	m.done()
	t.Logf("equal scales %d, alpha=0 %d, alpha>1 %d", equal, zeroAlpha, bigAlpha)
	t.Logf("RoundExact would differ on %d outputs, float64 multipliers on %d, inScale·(alpha/outScale) on %d",
		exactDiff, f64Diff, orderDiff)
	assert.Positive(t, exactDiff, "fixtures must distinguish the rounding modes")
	assert.Positive(t, f64Diff, "fixtures must distinguish float32 and float64 derivation")
	assert.Positive(t, orderDiff, "fixtures must pin the float32 association (inScale·alpha)/outScale")
	assert.Positive(t, equal)
	assert.Positive(t, len(fx.LeakyReLU)-equal)
	assert.Positive(t, zeroAlpha)
	assert.Positive(t, bigAlpha)
}

// refBilinear is an independent int64 transcription of TFLite's
// ResizeBilinearInteger; single selects the TFLITE_SINGLE_ROUNDING variant
// ((o + 2^19) >> 20), which LiteRT's default build does not use.
func refBilinear(src []int8, p ResizeParams, single bool) []int8 {
	scale := func(in, out int) int64 {
		if p.AlignCorners && out > 1 {
			return (1024*int64(in-1) + int64(out-1)/2) / int64(out-1)
		}
		return (1024*int64(in) + int64(out)/2) / int64(out)
	}
	interp := func(v int, sc int64, in int) (s, lo, hi int64) {
		s = int64(v) * sc
		if p.HalfPixel {
			s += sc/2 - 512
		}
		lo = max(s/1024, 0)
		hi = min((s+1023)/1024, int64(in-1))
		return
	}
	in, c := p.In, int64(p.In.C)
	at := func(y, x, ch int64) int64 { return int64(src[(y*int64(in.W)+x)*c+ch]) }
	hs, ws := scale(in.H, p.OutH), scale(in.W, p.OutW)
	out := make([]int8, 0, p.OutH*p.OutW*in.C)
	for oy := range p.OutH {
		sy, y0, y1 := interp(oy, hs, in.H)
		for ox := range p.OutW {
			sx, x0, x1 := interp(ox, ws, in.W)
			dy, dx := sy-1024*y0, sx-1024*x0
			for ch := range c {
				o := at(y0, x0, ch)*(1024-dy)*(1024-dx) + at(y1, x0, ch)*dy*(1024-dx) +
					at(y0, x1, ch)*(1024-dy)*dx + at(y1, x1, ch)*dy*dx
				var v int64
				switch {
				case single:
					v = (o + 1<<19) >> 20
				case o > 0:
					v = (o + 1<<19) / (1 << 20)
				default:
					v = (o - 1<<19) / (1 << 20)
				}
				out = append(out, int8(v))
			}
		}
	}
	return out
}

func TestResizeBilinearTFLite(t *testing.T) {
	fx := loadTFLiteOps2(t)
	m := &mismatchLog{t: t}
	ref := &mismatchLog{t: t}
	singleDiff := 0
	flags := map[[2]bool]int{}
	var onePixel, up, down, maxC int
	for i, c := range fx.Bilinear {
		p := ResizeParams{In: shapeOf(c.In), OutH: c.OutH, OutW: c.OutW, AlignCorners: c.AlignCorners, HalfPixel: c.HalfPixel}
		dst := make([]int8, len(c.Out))
		require.NoError(t, ResizeBilinear(dst, c.Src, p), "case %d", i)
		desc := func() string { return fmt.Sprintf("bilinear %d %+v", i, p) }
		m.compare(desc, dst, c.Out)
		ref.compare(desc, refBilinear(c.Src, p, false), c.Out)
		singleDiff += diffCount(refBilinear(c.Src, p, true), c.Out)
		flags[[2]bool{c.AlignCorners, c.HalfPixel}]++
		if min(p.In.H, p.In.W, p.OutH, p.OutW) == 1 {
			onePixel++
		}
		if p.OutH > p.In.H || p.OutW > p.In.W {
			up++
		}
		if p.OutH < p.In.H || p.OutW < p.In.W {
			down++
		}
		maxC = max(maxC, p.In.C)
	}
	m.done()
	ref.done()
	t.Logf("flags=%v one-pixel=%d up=%d down=%d maxC=%d; single rounding would differ on %d outputs",
		flags, onePixel, up, down, maxC, singleDiff)
	assert.Positive(t, singleDiff, "fixtures must distinguish the rounding")
	assert.Len(t, flags, 3)
	assert.Zero(t, flags[[2]bool{true, true}])
	assert.Positive(t, onePixel)
	assert.Positive(t, up)
	assert.Positive(t, down)
	assert.Equal(t, 40, maxC)
}

func TestLeakyReLUReference(t *testing.T) {
	g := newGen(26)
	m := &mismatchLog{t: t}
	for c := range 1500 {
		e := &exactF{}
		id, al := g.requant(), g.requant()
		switch g.r.IntN(6) {
		case 0:
			al = Requant{}
		case 1:
			al = Requant{Mult: []int32{1 << 30, 3 << 29, 5 << 28}[g.r.IntN(3)], Shift: int32(-g.r.IntN(6))}
		}
		sc := newRefScales(g.r, e, []Requant{id})
		sIn := e.mul(sc.sIn, sc.sW[0]) // sIn/sOut = M'(identity)
		// alpha = M'(alpha)/M'(identity), so alpha·sIn/sOut = M'(alpha)
		alpha := new(big.Rat).SetFrac(
			new(big.Int).Lsh(big.NewInt(int64(al.Mult)), uint(al.Shift+31)),
			new(big.Int).Lsh(big.NewInt(int64(id.Mult)), uint(id.Shift+31)))
		p := LeakyReLUParams{InZP: g.zp(), OutZP: g.zp(), Identity: id, Alpha: al}
		src := ramp()
		want := make([]int8, len(src))
		for i, x := range dequant(e, src, p.InZP, sIn) {
			y, _ := x.Rat(nil)
			if y.Sign() < 0 {
				y.Mul(y, alpha)
			}
			want[i] = quantizeRat(y, sc.sOut, p.OutZP, -128, 127)
		}
		require.False(t, e.inexact, "reference arithmetic was inexact")
		got := make([]int8, len(src))
		require.NoError(t, LeakyReLU(got, src, p))
		m.compare(func() string { return fmt.Sprintf("case %d %+v", c, p) }, got, want)
	}
	m.done()
}

func TestTFLiteOps2Hand(t *testing.T) {
	// alpha = 0: negative inputs map to the output zero point.
	id, al, err := QuantizeLeakyReLU(0.1, 0.1, 0)
	require.NoError(t, err)
	assert.Equal(t, Requant{Mult: 1 << 30, Shift: 1}, id)
	assert.Equal(t, Requant{}, al)
	dst := make([]int8, 3)
	p := LeakyReLUParams{InZP: 5, OutZP: -7, Identity: id, Alpha: al, Round: RoundTFLite}
	require.NoError(t, LeakyReLU(dst, []int8{-100, 5, 9}, p))
	assert.Equal(t, []int8{-7, -7, -3}, dst)
	// A multiplier below 2^-32 is TFLite's zero multiplier, not an error.
	_, al, err = QuantizeLeakyReLU(0.1, 0.1, 1e-12)
	require.NoError(t, err)
	assert.Equal(t, Requant{}, al)
	// alpha 0.5, equal scales: v = −3 → −1.5 → −1 (TFLite, ties up) / −2 (exact).
	_, al, err = QuantizeLeakyReLU(0.25, 0.25, 0.5)
	require.NoError(t, err)
	p = LeakyReLUParams{Identity: id, Alpha: al, Round: RoundTFLite}
	require.NoError(t, LeakyReLU(dst[:1], []int8{-3}, p))
	assert.Equal(t, int8(-1), dst[0])
	p.Round = RoundExact
	require.NoError(t, LeakyReLU(dst[:1], []int8{-3}, p))
	assert.Equal(t, int8(-2), dst[0])

	// Bilinear 1×2 → 1×4, no flags: scale 512; x = 0, 0.5, 1, 1.5 →
	// 10, (10+20)/2 = 15, 20, 20 (upper cell clamped).
	out := make([]int8, 4)
	require.NoError(t, ResizeBilinear(out, []int8{10, 20}, ResizeParams{In: Shape{H: 1, W: 2, C: 1}, OutH: 1, OutW: 4}))
	assert.Equal(t, []int8{10, 15, 20, 20}, out)
	// Ties round away from zero: (−1 + −2)/2 = −1.5 → −2, (1+2)/2 → 2.
	out = out[:3]
	require.NoError(t, ResizeBilinear(out, []int8{-1, -2}, ResizeParams{In: Shape{H: 1, W: 2, C: 1}, OutH: 1, OutW: 3, AlignCorners: true}))
	assert.Equal(t, []int8{-1, -2, -2}, out, "align corners 2→3: positions 0, 0.5, 1")
	require.NoError(t, ResizeBilinear(out, []int8{1, 2}, ResizeParams{In: Shape{H: 1, W: 2, C: 1}, OutH: 1, OutW: 3, AlignCorners: true}))
	assert.Equal(t, []int8{1, 2, 2}, out)
}

func TestTFLiteOps2Errors(t *testing.T) {
	inf, nan := float32(math.Inf(1)), float32(math.NaN())
	for _, c := range [][3]float32{
		{0, 1, 0.1}, {-1, 1, 0.1}, {inf, 1, 0.1}, {nan, 1, 0.1},
		{1, 0, 0.1}, {1, inf, 0.1}, {1, nan, 0.1},
		{1, 1, -0.1}, {1, 1, inf}, {1, 1, nan},
		{1e30, 1e-30, 0.1}, // identity ≥ 2^30
		{1, 1e-20, 0},      // identity overflow even with alpha 0
		{1, 1, 3e9},        // alpha multiplier ≥ 2^30
	} {
		_, _, err := QuantizeLeakyReLU(c[0], c[1], c[2])
		assert.Equal(t, ErrRequant, err, "%v", c)
	}

	x := make([]int8, 12)
	ok := Requant{Mult: 1 << 30, Shift: 0}
	bad := Requant{Mult: 5}
	assert.NoError(t, LeakyReLU(x, x, LeakyReLUParams{Identity: ok}))
	assert.Equal(t, ErrLength, LeakyReLU(x[:3], x, LeakyReLUParams{Identity: ok}))
	assert.Equal(t, ErrRequant, LeakyReLU(x, x, LeakyReLUParams{Identity: bad}))
	assert.Equal(t, ErrRequant, LeakyReLU(x, x, LeakyReLUParams{Identity: ok, Alpha: bad}))
	assert.Equal(t, ErrRequant, LeakyReLU(x, x, LeakyReLUParams{Identity: ok, Round: 2}))

	in := Shape{H: 1, W: 2, C: 3}
	rp := ResizeParams{In: in, OutH: 2, OutW: 2}
	assert.NoError(t, ResizeBilinear(x, x[:6], rp))
	for _, c := range []ResizeParams{
		{In: Shape{H: 0, W: 2, C: 3}, OutH: 2, OutW: 2},
		{In: in, OutH: 0, OutW: 2},
		{In: in, OutH: MaxElements, OutW: 2},
		{In: in, OutH: 2, OutW: 2, AlignCorners: true, HalfPixel: true},
		{In: Shape{H: 1, W: maxBilinearDim + 1, C: 1}, OutH: 1, OutW: 1},
		{In: Shape{H: 1, W: 2, C: 1}, OutH: 1, OutW: 3000}, // TFLite would read past the input
	} {
		assert.Equal(t, ErrShape, ResizeBilinear(x, x[:6], c), "%+v", c)
	}
	assert.Equal(t, ErrLength, ResizeBilinear(x[:11], x[:6], rp))
	assert.Equal(t, ErrLength, ResizeBilinear(x, x[:7], rp))
	// The largest in-bounds upscale of 2 pixels is accepted.
	big := ResizeParams{In: Shape{H: 1, W: 2, C: 1}, OutH: 1, OutW: 2048}
	assert.NoError(t, ResizeBilinear(make([]int8, 2048), x[:2], big))
}

func TestTFLiteOps2Alias(t *testing.T) {
	g := newGen(27)
	src := g.int8s(300)
	id, al, err := QuantizeLeakyReLU(0.05, 0.08, 0.1)
	require.NoError(t, err)
	for _, round := range []Rounding{RoundExact, RoundTFLite} {
		p := LeakyReLUParams{InZP: -3, OutZP: 7, Identity: id, Alpha: al, Round: round}
		want := make([]int8, len(src))
		require.NoError(t, LeakyReLU(want, src, p))
		got := append([]int8(nil), src...)
		require.NoError(t, LeakyReLU(got, got, p))
		assert.Equal(t, want, got, "LeakyReLU in place")
	}
}

func TestTFLiteOps2NoAllocs(t *testing.T) {
	src, dst := make([]int8, 4*4*8), make([]int8, 4*4*8)
	up := make([]int8, 8*8*8)
	id, al, err := QuantizeLeakyReLU(0.05, 0.08, 0.1)
	require.NoError(t, err)
	rp := ResizeParams{In: Shape{H: 4, W: 4, C: 8}, OutH: 8, OutW: 8, HalfPixel: true}
	for _, round := range []Rounding{RoundExact, RoundTFLite} {
		p := LeakyReLUParams{InZP: -3, OutZP: 7, Identity: id, Alpha: al, Round: round}
		for name, f := range map[string]func(){
			"QuantizeLeakyReLU": func() { _, _, _ = QuantizeLeakyReLU(0.05, 0.08, 0.1) },
			"LeakyReLU":         func() { _ = LeakyReLU(dst, src, p) },
			"LeakyReLU error":   func() { _ = LeakyReLU(dst[:1], src, p) },
			"ResizeBilinear":    func() { _ = ResizeBilinear(up, src, rp) },
			"Bilinear error":    func() { _ = ResizeBilinear(up[:1], src, rp) },
		} {
			assert.Zero(t, testing.AllocsPerRun(50, f), "%s round=%d", name, round)
		}
	}
}
